# Gpixel update: once the app exits, replace the exe and relaunch. On failure, restore the previous exe.
$ErrorActionPreference = 'Stop'
$appPid = {0}
$target = {1}
$new = {2}
$staging = {3}
$log = {4}
$old = $target + '.old'
function Log([string]$m) {{ try {{ Add-Content -LiteralPath $log -Value ((Get-Date -Format 's') + ' ' + $m) -Encoding UTF8 }} catch {{}} }}
function Alert([string]$m) {{
    try {{
        Add-Type -AssemblyName PresentationFramework
        [System.Windows.MessageBox]::Show("Could not install the Gpixel update. The previous version was kept.`n`n$m`n`nLog: $log", 'Gpixel') | Out-Null
    }} catch {{}}
}}
Log "update to $new"
for ($i = 0; $i -lt 600 -and (Get-Process -Id $appPid -ErrorAction SilentlyContinue); $i++) {{ Start-Sleep -Milliseconds 200 }}
if (Get-Process -Id $appPid -ErrorAction SilentlyContinue) {{ Log 'app did not exit'; Alert 'Gpixel did not exit.'; exit 1 }}
try {{
    if (Test-Path -LiteralPath $old) {{ Remove-Item -LiteralPath $old -Force }}
    Move-Item -LiteralPath $target -Destination $old
}} catch {{
    Log "move failed: $_"; Alert "$_"
    if (Test-Path -LiteralPath $target) {{ Start-Process -FilePath $target }}
    exit 1
}}
try {{
    Copy-Item -LiteralPath $new -Destination $target
}} catch {{
    Log "copy failed: $_"
    Remove-Item -LiteralPath $target -Force -ErrorAction SilentlyContinue
    Move-Item -LiteralPath $old -Destination $target
    Alert "$_"
    Start-Process -FilePath $target
    exit 1
}}
Unblock-File -LiteralPath $target -ErrorAction SilentlyContinue
Start-Process -FilePath $target -WorkingDirectory (Split-Path -Parent $target)
Start-Sleep -Seconds 2
Remove-Item -LiteralPath $old -Force -ErrorAction SilentlyContinue
Remove-Item -LiteralPath $staging -Recurse -Force -ErrorAction SilentlyContinue
Log 'done'

